#!/bin/sh
# test/dist/test_stability_tiers.sh -- every installed public header
# declares exactly one stability tier, and docs/abi-stability.md's tier
# table matches the headers.
#
#   * @stability stable        covered by the LTS promise: no incompatible
#                              change within a major (docs/abi-stability.md)
#   * @stability experimental  may change in any minor release
#
# The tag sits in the header's opening comment (line 3, under the
# copyright).  The doc table is GENERATED from the headers: rerun with
# XTC_TIERS_UPDATE=1 to rewrite the block between the
# <!-- tiers:begin --> / <!-- tiers:end --> markers, then commit it.
set -eu
LC_ALL=C; export LC_ALL   # stable sort order on every host
: "${XTC_SRC_DIR:?XTC_SRC_DIR must be set}"
SRC="$XTC_SRC_DIR"
INC="$SRC/src/inc"
DOC="$SRC/docs/abi-stability.md"

hdrs=$(sed -n '/^LIB_HDRS_PUBLIC/,/xtc_trace\.h$/p' "$SRC/dist/Makefile.in" |
	grep -oE 'xtc[a-z0-9_]*\.h' | sort -u)
work=$(mktemp -d "${TMPDIR:-/tmp}/xtctiers.XXXXXX") || exit 1
trap 'find "$work" -delete 2>/dev/null || true' EXIT INT TERM

rc=0
: > "$work/table"
for h in $hdrs; do
	n=$(grep -cE '^ \* @stability ' "$INC/$h" || true)
	t=$(sed -n 's/^ \* @stability \([a-z]*\)[[:space:]]*$/\1/p' "$INC/$h" | head -1)
	if [ "$n" -ne 1 ]; then
		echo "  [tiers] FAIL: $h has $n @stability lines (want exactly 1)" >&2
		rc=1
		continue
	fi
	case "$t" in
	stable|experimental) ;;
	*)	echo "  [tiers] FAIL: $h: unknown tier '$t'" >&2; rc=1; continue ;;
	esac
	printf '| `%s` | %s |\n' "$h" "$t" >> "$work/table"
done
[ "$rc" -eq 0 ] || exit 1

{
	echo '<!-- tiers:begin (generated by test/dist/test_stability_tiers.sh) -->'
	echo '| header | tier |'
	echo '|---|---|'
	sort "$work/table"
	echo '<!-- tiers:end -->'
} > "$work/block"

if [ "${XTC_TIERS_UPDATE:-0}" = 1 ]; then
	awk -v blk="$work/block" '
		/<!-- tiers:begin/ { while ((getline l < blk) > 0) print l; skip = 1; next }
		/<!-- tiers:end -->/ { skip = 0; next }
		!skip { print }' "$DOC" > "$work/doc"
	cp "$work/doc" "$DOC"
	echo "  [tiers] UPDATED: the tier table in docs/abi-stability.md"
	exit 0
fi

sed -n '/<!-- tiers:begin/,/<!-- tiers:end -->/p' "$DOC" > "$work/have"
if ! diff -u "$work/have" "$work/block" > "$work/diff"; then
	echo "  [tiers] FAIL: docs/abi-stability.md tier table is stale:" >&2
	head -20 "$work/diff" >&2
	echo "  rerun with XTC_TIERS_UPDATE=1 and commit the table" >&2
	exit 1
fi
ns=$(grep -c ' stable |' "$work/table" || true)
ne=$(grep -c ' experimental |' "$work/table" || true)
echo "  [tiers] OK: $((ns + ne)) installed headers, each one tier ($ns stable, $ne experimental); doc table current"
